-- Real profiles are used only in a rolled-back transaction; no data/permission change remains.
begin;
-- The launch flag turns on only in the rolled-back test transaction.
update public.feature_flags set is_enabled=true,rollout_percent=100 where key='community.enabled';
do $$
declare
  owner_user public.users; reader public.users; s uuid; c uuid; private_c uuid; free_c uuid; base uuid; role_a uuid; role_b uuid;
  msg uuid; private_msg uuid; sent uuid; report_id uuid; payload jsonb; result jsonb; item jsonb; channel_payload jsonb;
  owner_claims text; reader_claims text; rejected boolean; keyv uuid:=gen_random_uuid(); lastv timestamptz; n integer;
begin
  select * into owner_user from public.users where username='site_owner';
  select * into reader from public.users where username='denemeuser';
  select id into s from community_v2.servers where owner_id=owner_user.id limit 1;
  if s is null or reader.auth_user_id is null then raise exception 'Test önkoşulları eksik.'; end if;
  owner_claims:=jsonb_build_object('sub',owner_user.auth_user_id,'role','authenticated','session_id',coalesce(owner_user.active_session_id,gen_random_uuid()))::text;
  reader_claims:=jsonb_build_object('sub',reader.auth_user_id,'role','authenticated','session_id',coalesce(reader.active_session_id,gen_random_uuid()))::text;
  perform set_config('request.jwt.claims',owner_claims,true);
  select id into base from community_v2.roles where server_id=s and is_default;
  update community_v2.roles set permissions=array['channel.view','messages.read'] where id=base;
  role_a:=(public.community_v2_write('save_role',jsonb_build_object('server_id',s,'name','İnceleme doğrulama ekibi','color','#86d9ce','position',200,'permissions',array['messages.send','messages.self.delete','messages.self.edit','reports.review']))->>'id')::uuid;
  role_b:=(public.community_v2_write('save_role',jsonb_build_object('server_id',s,'name','Ek okur rolü','color','#abcdef','position',300,'permissions','[]'::jsonb))->>'id')::uuid;
  insert into community_v2.members(server_id,user_id) values(s,reader.id) on conflict(server_id,user_id) do update set state='active',timeout_until=null,last_message_at=null;
  delete from community_v2.member_roles where server_id=s and user_id=reader.id;
  perform public.community_v2_write('assign_roles',jsonb_build_object('server_id',s,'user_id',reader.id,'role_ids',array[role_a,role_b]));
  channel_payload:=jsonb_build_object('server_id',s,'name','Yavaş mod doğrulaması','topic','Geri alınan işlev testi.','position',999,'is_private',false,'role_ids','[]'::jsonb,'slowmode_seconds',60);
  c:=(public.community_v2_write('save_channel',channel_payload)->>'id')::uuid;
  free_c:=(public.community_v2_write('save_channel',channel_payload||jsonb_build_object('name','Serbest doğrulama','slowmode_seconds',0))->>'id')::uuid;
  private_c:=(public.community_v2_write('save_channel',channel_payload||jsonb_build_object('name','Özel inceleme','is_private',true))->>'id')::uuid;
  update community_v2.members set last_message_at=null where server_id=s and user_id=owner_user.id;
  msg:=(public.community_v2_write('send',jsonb_build_object('channel_id',c,'client_id',gen_random_uuid(),'body','Okuma buluşmasının başlangıç saati.'))->>'id')::uuid;
  update community_v2.members set last_message_at=null where server_id=s and user_id=owner_user.id;
  private_msg:=(public.community_v2_write('send',jsonb_build_object('channel_id',private_c,'client_id',gen_random_uuid(),'body','Özel ekip konuşması.'))->>'id')::uuid;
  -- If channel metadata is manageable the duration also updates with version control.
  perform public.community_v2_write('save_channel',channel_payload||jsonb_build_object('channel_id',c,'version',1,'slowmode_seconds',120));
  if (select slowmode_seconds from community_v2.channels where id=c)<>120 then raise exception 'Yavaş mod kaydedilmedi.'; end if;
  rejected:=false; begin perform public.community_v2_write('save_channel',channel_payload||jsonb_build_object('channel_id',c,'version',1)); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Eski sürüm yavaş modu ezdi.'; end if;
  rejected:=false; begin perform public.community_v2_write('save_channel',channel_payload||jsonb_build_object('slowmode_seconds',21601)); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Süre üst sınırı aşıldı.'; end if;
  perform set_config('request.jwt.claims',reader_claims,true);
  payload:=jsonb_build_object('channel_id',c,'client_id',keyv,'body','Buluşmaya katılıyorum.');
  sent:=(public.community_v2_write('send',payload)->>'id')::uuid;
  if (public.community_v2_write('send',payload)->>'id')::uuid<>sent then raise exception 'Yavaş mod idempotence bozuldu.'; end if;
  update community_v2.members set last_message_at=null where server_id=s and user_id=reader.id;
  select last_sent_at into lastv from community_v2.message_cooldowns where channel_id=c and user_id=reader.id;
  rejected:=false; begin perform public.community_v2_write('send',payload||jsonb_build_object('client_id',gen_random_uuid())); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Yavaş mod atlandı.'; end if;
  if (select last_sent_at from community_v2.message_cooldowns where channel_id=c and user_id=reader.id)<>lastv then raise exception 'Başarısız gönderim süreyi uzattı.'; end if;
  perform public.community_v2_write('edit_message',jsonb_build_object('channel_id',c,'message_id',sent,'version',1,'body','Buluşmaya zamanında katılıyorum.'));
  perform public.community_v2_write('delete_message',jsonb_build_object('channel_id',c,'message_id',sent));
  rejected:=false; begin perform public.community_v2_write('send',payload||jsonb_build_object('client_id',gen_random_uuid())); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Silmek yavaş modu sıfırladı.'; end if;
  perform public.community_v2_write('send',payload||jsonb_build_object('channel_id',free_c,'client_id',gen_random_uuid()));
  result:=public.community_v2_read('server',jsonb_build_object('server_id',s));
  select value into item from jsonb_array_elements(result->'channels') where value->>'id'=c::text;
  if (item->>'next_send_at')::timestamptz<=now() or result->>'server_now' is null or (item->>'slowmode_seconds')::int<>120 then raise exception 'Sunucu bekleme bilgisi eksik.'; end if;
  -- An exemption on one role is enough; a lower role closed permission does not take it back.
  update community_v2.roles set permissions=array['slowmode.bypass'] where id=role_b;
  update community_v2.members set last_message_at=null where server_id=s and user_id=reader.id;
  perform public.community_v2_write('send',payload||jsonb_build_object('client_id',gen_random_uuid()));
  rejected:=false; begin perform public.community_v2_write('send',payload||jsonb_build_object('client_id',gen_random_uuid())); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Muafiyet temel spam sınırını kaldırdı.'; end if;
  update community_v2.roles set permissions='{}' where id=role_b;
  update community_v2.members set last_message_at=null where server_id=s and user_id=reader.id;
  rejected:=false; begin perform public.community_v2_write('send',payload||jsonb_build_object('client_id',gen_random_uuid())); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Muafiyet kaybı anlık uygulanmadı.'; end if;
  update community_v2.message_cooldowns set last_sent_at=clock_timestamp()-interval '121 seconds' where channel_id=c and user_id=reader.id;
  perform public.community_v2_write('send',payload||jsonb_build_object('client_id',gen_random_uuid()));
  -- A channel access manager cannot change the wait time without metadata permission.
  update community_v2.roles set permissions=array['channels.permissions.manage'] where id=role_b;
  rejected:=false; begin perform public.community_v2_write('save_channel',channel_payload||jsonb_build_object('channel_id',c,'version',2,'slowmode_seconds',0)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Erişim izniyle yavaş mod kapatıldı.'; end if;
  -- Report: a read-only/restricted user can also report a message they can reach.
  update community_v2.members set timeout_until=now()+interval '1 hour' where server_id=s and user_id=reader.id;
  payload:=jsonb_build_object('channel_id',c,'message_id',msg,'reason','spoiler','note','Spoiler etiketi eksik görünüyor.');
  result:=public.community_v2_moderation('report',payload);
  if (result->>'duplicate')::boolean then raise exception 'İlk şikâyet tekrar sayıldı.'; end if;
  if not (public.community_v2_moderation('report',payload||jsonb_build_object('note','İkinci açıklama'))->>'duplicate')::boolean then raise exception 'Tekrar şikâyet tekilleştirilmedi.'; end if;
  select id into report_id from community_v2.message_reports where message_id=msg and reporter_id=reader.id;
  if (select note from community_v2.message_reports where id=report_id)<>'Spoiler etiketi eksik görünüyor.' then raise exception 'Tekrar istek ilk notu ezdi.'; end if;
  rejected:=false; begin perform public.community_v2_moderation('list',jsonb_build_object('server_id',s)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Timeout yönetim incelemesini aşabildi.'; end if;
  update community_v2.members set timeout_until=null where server_id=s and user_id=reader.id;
  rejected:=false; begin perform public.community_v2_moderation('report',payload||jsonb_build_object('channel_id',private_c,'message_id',private_msg)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Özel mesaj erişimsiz bildirildi.'; end if;
  rejected:=false; begin perform public.community_v2_moderation('report',payload||jsonb_build_object('message_id',sent)); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Kendi mesajı bildirildi.'; end if;
  insert into community_v2.channel_roles(server_id,channel_id,role_id) values(s,private_c,role_b);
  update community_v2.message_reports set created_at=clock_timestamp()-interval '10 seconds' where id=report_id;
  perform public.community_v2_moderation('report',payload||jsonb_build_object('channel_id',private_c,'message_id',private_msg));
  result:=public.community_v2_moderation('list',jsonb_build_object('server_id',s));
  if jsonb_array_length(result)<>2 then raise exception 'İzinli inceleme OR birleşimi bozuk.'; end if;
  delete from community_v2.channel_roles where channel_id=private_c;
  result:=public.community_v2_moderation('list',jsonb_build_object('server_id',s));
  if jsonb_array_length(result)<>1 or result->0->>'id'<>report_id::text then raise exception 'Özel oda şikâyeti sızdı.'; end if;
  if jsonb_array_length(public.community_v2_moderation('list',jsonb_build_object('server_id',s,'before',result->0->>'cursor')))<>0 then raise exception 'Şikâyet sayfalaması tekrar üretti.'; end if;
  rejected:=false; begin perform public.community_v2_moderation('decide',jsonb_build_object('server_id',s,'report_id',(select id from community_v2.message_reports where message_id=private_msg),'version',1,'status','resolved')); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Özel şikâyet erişimsiz kapatıldı.'; end if;
  rejected:=false; begin perform public.community_v2_write('delete_message',jsonb_build_object('channel_id',c,'message_id',msg)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'İnceleme izni silme hakkı verdi.'; end if;
  payload:=jsonb_build_object('server_id',s,'report_id',report_id,'version',1,'status','resolved','note','Etiket önerisi incelendi.');
  perform public.community_v2_moderation('decide',payload);
  perform public.community_v2_moderation('decide',payload);
  rejected:=false; begin perform public.community_v2_moderation('decide',payload||jsonb_build_object('status','dismissed')); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Kaydedilen karar eski sürümle ezildi.'; end if;
  if exists(select 1 from community_v2.audit where target_id=report_id and details<>'{}'::jsonb) then raise exception 'Genel denetim kaydına özel şikâyet bilgisi taşındı.'; end if;
  if (select deleted_at from community_v2.messages where id=msg) is not null then raise exception 'Karar mesajı kendiliğinden sildi.'; end if;
  update community_v2.roles set permissions=array_remove(permissions,'reports.review') where id=role_a;
  rejected:=false; begin perform public.community_v2_moderation('list',jsonb_build_object('server_id',s)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'İnceleme yetki kaybı anlık uygulanmadı.'; end if;
  perform set_config('request.jwt.claims',owner_claims,true);
  perform public.community_v2_write('delete_message',jsonb_build_object('channel_id',c,'message_id',msg));
  result:=public.community_v2_moderation('list',jsonb_build_object('server_id',s,'status','resolved'));
  if result->0->'message'->>'body'<>'' or result->0->'message'->>'deleted_at' is null then raise exception 'Şikâyette silinen metin kaldı.'; end if;
  -- Limit and ACL validation happen on the server side a real client cannot pass.
  if has_table_privilege('authenticated','community_v2.message_reports','SELECT') or has_table_privilege('anon','community_v2.message_cooldowns','SELECT') or has_function_privilege('anon','public.community_v2_moderation(text,jsonb)','EXECUTE') then raise exception 'Moderasyon ACL açık.'; end if;
  if has_function_privilege('authenticated','community_v2.message_write(text,jsonb)','EXECUTE') then raise exception 'Mesaj yardımcısı doğrudan açık.'; end if;
  update community_v2.message_reports set created_at=clock_timestamp()-interval '10 seconds' where reporter_id=reader.id;
  select count(*) into n from community_v2.message_reports where reporter_id=reader.id and created_at>now()-interval '24 hours';
  for i in n..19 loop
    insert into community_v2.messages(channel_id,seq,author_id,client_id,body) values(c,1000+i,owner_user.id,gen_random_uuid(),'Okuma etkinliği bilgilendirmesi.') returning id into msg;
    insert into community_v2.message_reports(server_id,channel_id,message_id,reporter_id,reason,created_at) values(s,c,msg,reader.id,'spam',now()-interval '1 minute');
  end loop;
  insert into community_v2.messages(channel_id,seq,author_id,client_id,body) values(c,2000,owner_user.id,gen_random_uuid(),'Yeni okuma programı.') returning id into msg;
  perform set_config('request.jwt.claims',reader_claims,true);
  rejected:=false; begin perform public.community_v2_moderation('report',jsonb_build_object('channel_id',c,'message_id',msg,'reason','spam')); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Günlük şikâyet sınırı aşıldı.'; end if;
  raise notice 'PASS: yavaş mod, OR muafiyeti, tekrar/silme, sürüm, özel oda şikâyeti, inceleme, karar, silinen içerik, limit ve ACL';
end $$;
rollback;
